let approverDecision;
try {
  approverDecision = JSON.parse(approverResponse);
} catch (error) {
  console.log('❌ Failed to parse Approver JSON response');
  approverDecision = {
    approved: false,
    final_feedback: 'Invalid JSON response from Approver',
    send_back_instructions: 'Approver returned invalid JSON. Please retry section.'
  };
}

console.log(`✅ Approver Decision: ${approverDecision.approved ? 'APPROVED' : 'REJECTED'}`);
console.log(`💼 Feedback: ${approverDecision.final_feedback}`);

if (!approverDecision.approved) {
  console.log(`⚠️ Approver rejection: ${approverDecision.send_back_instructions}`);

  return {
    json: {
      ...taskData,
      approver_approved: false,
      approver_decision: approverDecision,
      workflow_action: 'POST_APPROVER_REJECTION'
    }
  };
}

// Both Checker and Approver approved - proceed to finalization
console.log('🎉 Section fully approved by MCA workflow!');

return {
  json: {
    ...taskData,
    approver_approved: true,
    approver_decision: approverDecision,
    checker_decision: taskData.checker_decision,
    final_markdown: taskData.maker_output,
    workflow_action: 'GENERATE_PDF'
  }
};

