// PREPARE FINAL COMMENT WITH SECTION CONTENT
const taskData = $input.first().json;

console.log(`📄 Preparing final comment for: ${taskData.company_name}`);
console.log(`📝 Section: ${taskData.section_name}`);

// Create complete comment with header and content
let finalComment = `🎉 **DUE DILIGENCE SECTION COMPLETED**\n\n`;
finalComment += `📄 **Company:** ${taskData.company_name}\n`;
finalComment += `📝 **Section:** ${taskData.section_name}\n`;
finalComment += `**Generated:** ${(new Date()).toISOString()}\n`;
finalComment += `**Quality Score:** ${taskData.checker_decision.quality_score}/10\n`;
finalComment += `**Website:** ${taskData.website_url}\n\n`;
finalComment += `---\n\n`;

// Add the approved section content
finalComment += taskData.final_markdown;

// Add metadata footer
finalComment += `\n\n---\n\n`;
finalComment += `## Quality Assurance\n\n`;
finalComment += `**Checker Validation:** ✅ Approved (Score: ${taskData.checker_decision.quality_score}/10)\n`;
finalComment += `**Approver Review:** ✅ Approved\n`;
finalComment += `**Knowledge Base Sources:** ${taskData.total_chunks} chunks\n`;
finalComment += `**FinBERT Analysis:** ${taskData.finbert_available ? '✅ Available' : '❌ Not Available'}\n`;
finalComment += `**Website Data:** ${taskData.website_content_available ? '✅ Available' : '❌ Not Available'}\n`;
finalComment += `\n⏰ **Completed:** ${(new Date()).toISOString()}`;

return {
  json: {
    ...taskData,
    final_comment: finalComment,
    workflow_action: 'POST_FINAL_COMMENT'
  }
};
